mapper.select:
SELECT * FROM departure_schedule
WHERE train_id = #{trainId}
ORDER BY departure_time ASC

SELECT * FROM departure_schedule
WHERE departure_time BETWEEN #{startTime} AND #{endTime}
ORDER BY departure_time ASC

SELECT ds.* 
FROM departure_schedule ds
INNER JOIN router r ON ds.router_id = r.router_id
WHERE ds.train_id = #{trainId}
AND ds.departure_time < #{endTime}
AND DATE_ADD(ds.departure_time, INTERVAL r.total_duration MINUTE) > #{startTime}
